"""
Retrying HTTP requests -- the classic *stamina* use case.

The example uses a fake HTTP client so that it runs without network access and
without third-party dependencies, but the shape of the code is exactly what you
would write with, say, httpx or requests.

Run me with::

    python examples/http_requests.py
"""

from __future__ import annotations

import itertools
import logging

import stamina


logging.basicConfig(level=logging.INFO, format="%(message)s")


class HTTPError(Exception):
    """Stand-in for httpx.HTTPError."""


class HTTPStatusError(HTTPError):
    """Stand-in for httpx.HTTPStatusError."""

    def __init__(self, status_code: int) -> None:
        super().__init__(f"server returned {status_code}")
        self.status_code = status_code


_RESPONSES = itertools.chain(
    [HTTPStatusError(503), HTTPStatusError(502)], itertools.repeat(None)
)


def _get(url: str) -> dict[str, str]:
    """A flaky GET that fails twice before it succeeds."""
    if (exc := next(_RESPONSES)) is not None:
        raise exc

    return {"url": url, "status": "ok"}


# 1. Retry on an exception type.
@stamina.retry(on=HTTPError, attempts=5, wait_initial=0.05, wait_max=0.2)
def fetch(url: str) -> dict[str, str]:
    return _get(url)


# 2. Retry on a predicate: server errors are transient, client errors are not.
def is_transient(exc: Exception) -> bool:
    if isinstance(exc, HTTPStatusError):
        return exc.status_code >= 500

    return isinstance(exc, HTTPError)


@stamina.retry(on=is_transient, attempts=3, wait_initial=0.05, wait_max=0.2)
def fetch_only_server_errors(url: str) -> dict[str, str]:
    raise HTTPStatusError(404)  # 404 is *not* retried -- it fails immediately.


def main() -> None:
    print("fetching with retries:", fetch("https://example.com/api"))

    try:
        fetch_only_server_errors("https://example.com/nope")
    except HTTPStatusError as e:
        print(f"gave up immediately on a client error: {e}")


if __name__ == "__main__":
    main()

